package approvals

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// Golden bytes were generated by this same business mutation on f0aa82bb.
// Changing either serialization shape or the original pruning policy breaks it.
func baselineBusinessWrite(t *testing.T) *Service {
	t.Helper()
	s := New(filepath.Join(t.TempDir(), "approvals"), nil)
	now := time.Date(2026, 10, 29, 12, 0, 0, 0, time.UTC)
	s.SetClock(func() time.Time { return now })
	if err := s.store.update(func(doc *file) error {
		doc.LastNumber = 10
		doc.extra = map[string]json.RawMessage{"business_extension": json.RawMessage(`{ "keep": true }`)}
		for i, status := range []string{StatusExecuted, StatusFailed, StatusRejected, StatusExpired, StatusUnknown} {
			doc.put(Approval{ID: "appr_" + status, Number: i + 1, Status: status,
				Action: "review_fixture", Env: "stg", RequesterThread: "local_golden", CreatedAt: now, ExpiresAt: now.Add(time.Hour),
				Execution: &Execution{LeaseID: "fixture", FinishedAt: now}, Result: map[string]any{"ok": true}})
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	return s
}

func TestThreadInboxBusinessBytesMatchBaseline(t *testing.T) {
	t.Parallel()
	s := baselineBusinessWrite(t)
	want, err := os.ReadFile("testdata/thread_inbox_f0aa82bb.json")
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 2; i++ {
		raw, err := os.ReadFile(s.store.path)
		if err != nil || !bytes.Equal(raw, want) {
			t.Fatalf("business bytes differ from f0aa82bb: %v\n%s", err, raw)
		}
		if bytes.Contains(raw, []byte("thread_inbox")) {
			t.Fatal("delivery metadata serialized")
		}
		if err := s.retryThreadInbox(context.Background(), func(context.Context, string, string, string) error { return nil }); err != nil {
			t.Fatal(err)
		}
	}
}

// Serial: replaces the process-wide diagnostic logger.
func TestThreadInboxBusinessPruningIsCounted(t *testing.T) {
	previous := slog.Default()
	var log bytes.Buffer
	slog.SetDefault(slog.New(slog.NewTextHandler(&log, nil)))
	t.Cleanup(func() { slog.SetDefault(previous) })

	s := New(filepath.Join(t.TempDir(), "approvals"), nil)
	if err := s.store.update(func(doc *file) error {
		for i := 0; i < keepClosed+3; i++ {
			doc.put(Approval{ID: fmt.Sprintf("appr_%d", i), Status: StatusFailed})
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	if !bytes.Contains(log.Bytes(), []byte("approval business records pruned")) || !bytes.Contains(log.Bytes(), []byte("count=3")) {
		t.Fatalf("pruning not counted: %s", log.String())
	}
}
